using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Expenses.Dtos;using Namaa.Domain.Common.Results;namespace Namaa.Application.Expenses.Queries.GetExpenses;public sealed class GetExpensesQueryHandler(IExpenseRepository repository):IRequestHandler<GetExpensesQuery,Result<IReadOnlyList<ExpenseDto>>>{public async Task<Result<IReadOnlyList<ExpenseDto>>>Handle(GetExpensesQuery request,CancellationToken cancellationToken)=>Result.Success<IReadOnlyList<ExpenseDto>>((await repository.GetAllAsync(cancellationToken)).Select(ExpenseDto.FromEntity).ToList());}
